package com.keepcalm.placementportal.repository;import com.keepcalm.placementportal.entity.Offer;import com.keepcalm.placementportal.enums.OfferStatus;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.util.*;public interface OfferRepository extends JpaRepository<Offer,Long>{Page<Offer> findByStudentId(Long studentId,Pageable p);Optional<Offer> findByIdAndStudentId(Long id,Long studentId);Optional<Offer> findByIdAndInstitutionId(Long id,Long iid);@Query("select o from Offer o where o.institution.id=:iid and (:status is null or o.status=:status) and (:companyId is null or o.company.id=:companyId)")Page<Offer> adminSearch(@Param("iid")Long iid,@Param("status")OfferStatus status,@Param("companyId")Long companyId,Pageable p);long countByInstitutionIdAndStatus(Long iid,OfferStatus status);}
